ALTER TABLE public.workspaces ADD COLUMN contractor_intake_progress jsonb;
ALTER TABLE public.platform_settings ADD COLUMN contractor_price_mapping jsonb;
CREATE FUNCTION public.contractor_save_progress(_ws uuid,_step integer,_reviewed integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p jsonb;BEGIN IF _step NOT BETWEEN 0 AND 6 OR _reviewed NOT BETWEEN 0 AND 6 OR NOT public.network_workspace_access(_ws,true) OR NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.workspace_id=_ws AND m.user_id=auth.uid() AND m.role='owner' AND m.removed_at IS NULL AND w.provider_subtype='independent_contractor' AND NOT w.is_test_account) THEN RAISE EXCEPTION 'Contractor owner required';END IF;SELECT coalesce(contractor_intake_progress,'{}') INTO p FROM public.workspaces WHERE id=_ws FOR UPDATE;UPDATE public.workspaces SET contractor_intake_progress=jsonb_build_object('step',_step,'completed',(SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT DISTINCT x FROM jsonb_array_elements(coalesce(p->'completed','[]')||jsonb_build_array(_reviewed)) x) t)) WHERE id=_ws;END $$;
REVOKE ALL ON FUNCTION public.contractor_save_progress(uuid,integer,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.contractor_save_progress(uuid,integer,integer) TO authenticated,service_role;
CREATE FUNCTION public.contractor_trip_relationship_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE receiver uuid;source_ws uuid;BEGIN IF TG_OP='UPDATE' AND NEW.assigned_to IS NOT DISTINCT FROM OLD.assigned_to AND NEW.network_provider_workspace_id IS NOT DISTINCT FROM OLD.network_provider_workspace_id AND NEW.transport_type IS NOT DISTINCT FROM OLD.transport_type AND NEW.vehicle_id IS NOT DISTINCT FROM OLD.vehicle_id THEN RETURN NEW;END IF;receiver:=NEW.network_provider_workspace_id;IF receiver IS NULL AND NEW.assigned_to IS NOT NULL THEN SELECT m.workspace_id INTO receiver FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=NEW.assigned_to AND m.role='owner' AND m.removed_at IS NULL AND w.provider_subtype='independent_contractor';END IF;IF EXISTS(SELECT 1 FROM public.workspaces WHERE id=receiver AND provider_subtype='independent_contractor') THEN SELECT source_workspace_id INTO source_ws FROM public.trip_distributions WHERE id=NEW.network_distribution_id;IF source_ws IS NULL THEN SELECT workspace_id INTO source_ws FROM public.ride_requests WHERE id=NEW.ride_request_id;END IF;IF source_ws IS NULL THEN SELECT m.workspace_id INTO source_ws FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=NEW.created_by AND m.role='owner' AND m.removed_at IS NULL AND w.provider_subtype='nemt_business';END IF;IF NEW.trip_kind<>'passenger' OR NEW.transport_type<>'ambulatory' OR NOT public.contractor_connected(source_ws,receiver) OR NOT public.pass4p_service_eligible(receiver,'ambulatory',NEW.vehicle_id) THEN RAISE EXCEPTION 'Active connected eligible ambulatory contractor required';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER contractor_trip_relationship_boundary BEFORE INSERT OR UPDATE ON public.trips FOR EACH ROW EXECUTE FUNCTION public.contractor_trip_relationship_guard();
CREATE FUNCTION public.contractor_legacy_directory_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.workspaces WHERE id=NEW.workspace_id AND provider_subtype='independent_contractor') THEN NEW.description:=NULL;NEW.business_contact_email:=NULL;NEW.business_contact_phone:=NULL;NEW.contact_email_public:=false;NEW.contact_phone_public:=false;END IF;RETURN NEW;END $$;
CREATE TRIGGER contractor_public_field_boundary BEFORE INSERT OR UPDATE ON public.provider_network_profiles FOR EACH ROW EXECUTE FUNCTION public.contractor_legacy_directory_guard();
CREATE OR REPLACE FUNCTION public.provider_network_entitled(_ws uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM public.workspaces WHERE id=_ws AND provider_subtype='independent_contractor') THEN coalesce((public.contractor_evidence_summary(_ws)->>'eligible')::boolean,false) ELSE EXISTS(SELECT 1 FROM public.subscriptions s JOIN public.workspace_members m ON m.workspace_id=s.workspace_id AND m.user_id=s.user_id WHERE s.workspace_id=_ws AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND ((s.price_id='nemt_membership_monthly_v2' AND s.status IN ('active','trialing') AND (s.current_period_end IS NULL OR s.current_period_end>now())) OR (s.price_id='nemt_provider_base_monthly' AND s.status='trialing' AND s.network_addon_status='trialing') OR (s.price_id='nemt_provider_base_monthly' AND s.status='active' AND s.current_period_end>now() AND (s.network_addon_status='active' OR (s.network_addon_status='canceling' AND s.network_addon_cancel_at>now()))))) END $$;
CREATE FUNCTION public.contractor_configure_mapping(_environment text,_price text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') OR _environment NOT IN ('sandbox','live') OR _price !~ '^price_[A-Za-z0-9]+$' THEN RAISE EXCEPTION 'Master Admin and valid mapping reference required';END IF;UPDATE public.platform_settings SET contractor_price_mapping=coalesce(contractor_price_mapping,'{}')||jsonb_build_object(_environment,jsonb_build_object('priceId',_price,'verified',false,'amountCents',2000,'interval','month')),updated_at=now(),updated_by=auth.uid();INSERT INTO public.account_security_audit(user_id,sender_mfn_id,event_type,result) VALUES(auth.uid(),(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid()),'contractor_mapping_prepared',jsonb_build_object('environment',_environment,'verified',false));END $$;
REVOKE ALL ON FUNCTION public.contractor_configure_mapping(text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.contractor_configure_mapping(text,text) TO authenticated,service_role;